input.command:
cd D:\pal
$checks = @()
$checks += [pscustomobject]@{name='backend_root_health_status_ok'; actual=[string](Invoke-RestMethod 'http://127.0.0.1:8082/health' -TimeoutSec 10).status; expected='ok'}
$checks += [pscustomobject]@{name='backend_api_v1_health_status_ok'; actual=[string](Invoke-RestMethod 'http://127.0.0.1:8082/api/v1/health' -TimeoutSec 10).status; expected='ok'}
$body = (Invoke-WebRequest 'http://127.0.0.1:8082/api/v1/companies' -UseBasicParsing -TimeoutSec 20).Content
$names = ($body | ConvertFrom-Json).name -join ';'
$hit = 0
foreach ($frag in 'Asterleaf','BIMAKAVACH','PAL Test Company') { if ($names -match [regex]::Escape($frag)) { $hit++ } }
$checks += [pscustomobject]@{name='three_expected_company_names_served_from_user_database'; actual=$hit; expected=3}
$pg = 0; $sock = New-Object System.Net.Sockets.TcpClient
try { $sock.Connect('127.0.0.1',5432); if ($sock.Connected) { $pg = 1 } } catch { $pg = 0 } finally { $sock.Close() }
$checks += [pscustomobject]@{name='user_provided_postgres_5432_reachable'; actual=$pg; expected=1}
Push-Location backend
$cur = (.\\.venv\Scripts\python.exe -m alembic current 2>&1 | Out-String)
$heads = (.\\.venv\Scripts\python.exe -m alembic heads 2>&1 | Out-String)
Pop-Location
$curTag = 'none'; if ($cur -match '(0\d{3}_[a-z0-9_]+)') { $curTag = $Matches[1] }
$headTag = 'none'; if ($heads -match '(0\d{3}_[a-z0-9_]+)') { $headTag = $Matches[1] }
$checks += [pscustomobject]@{name='alembic_db_at_0012_head_ahead_at_0013'; actual=("$curTag|$headTag"); expected='0012_bank_tally_source|0013_add_audit_entity_types'}
$checks += [pscustomobject]@{name='audit_route_present_and_vouchers_route_absent_in_working_tree'; actual=((Get-ChildItem src\routes\*.tsx | Where-Object { $_.Name -eq 'audit.tsx' }).Count * 10 - (Get-ChildItem src\routes\*.tsx | Where-Object { $_.Name -eq 'vouchers.tsx' }).Count); expected=10}
$payload = [pscustomobject]@{version=1; checks=$checks}
Write-Output ('{"harnessVerification":' + (ConvertTo-Json -Compress -Depth 4 $payload) + '}')

